SELECT
  ((((((((SYNALOG_NUMBER_TEXT(2024)) || ('-'))) || ((CASE WHEN LENGTH(SYNALOG_NUMBER_TEXT(3)) >= 2 THEN SUBSTR(SYNALOG_NUMBER_TEXT(3), 1, 2) ELSE SUBSTR(REPLACE(HEX(ZEROBLOB(2)), '00', '0'), 1, 2 - LENGTH(SYNALOG_NUMBER_TEXT(3))) || SYNALOG_NUMBER_TEXT(3) END)))) || ('-'))) || ((CASE WHEN LENGTH(SYNALOG_NUMBER_TEXT(5)) >= 2 THEN SUBSTR(SYNALOG_NUMBER_TEXT(5), 1, 2) ELSE SUBSTR(REPLACE(HEX(ZEROBLOB(2)), '00', '0'), 1, 2 - LENGTH(SYNALOG_NUMBER_TEXT(5))) || SYNALOG_NUMBER_TEXT(5) END))) AS s;